import csv

def clean_row(row):
    name = row["name"].strip().title()
    score_text = row["score"].strip()

    if name == "":
        return None

    try:
        score = int(score_text)
    except ValueError:
        return None

    if score < 0 or score > 100:
        return None

    return {"name": name, "score": score}

with open("data/students.csv", "r") as file:
    reader = csv.DictReader(file)
    for row in reader:
        print(clean_row(row))

